import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;

/**
 * Content-only 64-bit digest of a query-algebra subtree, used by the packed join kernels to break exact cost ties
 * deterministically.
 * <p>
 * The digest covers operator signatures (which include variable names, constant values and operator options) and the
 * child order of the tree. It never includes packed relation, symbol or object IDs, which are assigned in query-text
 * order: two textually reordered occurrences of the same join factor therefore share one digest, and a plan choice that
 * falls back to the digest cannot depend on where a factor was written. For the same reason the name of an anonymous
 * variable without a value (a blank node, collection or path intermediate) is excluded: the parser numbers those names
 * in query-text order, so they are not content.
 */
final class PackedRelationDigest extends AbstractQueryModelVisitor<RuntimeException> {

	private static final long NODE_START = 0x4e4f444520535441L;
	private static final long NODE_END = 0x4e4f444520454e44L;
	private static final long ANONYMOUS_VARIABLE = 0x414e4f4e20564152L;

	private long hash = PackedPrimitiveHash.SEED;

	private PackedRelationDigest() {
	}

	/** Returns a non-zero content digest of the supplied subtree (a relation or a scalar condition). */
	static long digest(QueryModelNode expression) {
		PackedRelationDigest visitor = new PackedRelationDigest();
		expression.visit(visitor);
		long digest = PackedPrimitiveHash.finish(visitor.hash);
		return digest == 0L ? 1L : digest;
	}

	/** Composes two child digests into the digest of the binary plan node that combines them. */
	static long compose(long leftDigest, long rightDigest, int physicalImplementation) {
		long composed = PackedPrimitiveHash.step(PackedPrimitiveHash.SEED, leftDigest);
		composed = PackedPrimitiveHash.step(composed, rightDigest);
		long digest = PackedPrimitiveHash.finish(PackedPrimitiveHash.step(composed, physicalImplementation));
		return digest == 0L ? 1L : digest;
	}

	@Override
	public void meet(Var node) {
		if (node.isAnonymous() && !node.hasValue()) {
			hash = PackedPrimitiveHash.step(hash, NODE_START);
			hash = PackedPrimitiveHash.step(hash, ANONYMOUS_VARIABLE);
			hash = PackedPrimitiveHash.step(hash, NODE_END);
			return;
		}
		meetNode(node);
	}

	@Override
	protected void meetNode(QueryModelNode node) {
		hash = PackedPrimitiveHash.step(hash, NODE_START);
		hash = PackedPrimitiveHash.step(hash, node.getSignature().hashCode());
		node.visitChildren(this);
		hash = PackedPrimitiveHash.step(hash, NODE_END);
	}
}
